select package_code,tenant_id,order_code,industry_code,app_ver_code
from vm_order_devices
where tenant_id = #{tenantId}
and device_code = #{deviceCode}

    and industry_code = #{industryCode}

and delete_flag = '0'
and ord_status in (0,1,2)
order by update_time desc

